function storageKey(){return 'blh-analysis-journal:'+(window.BLH_AUTH?.user?.id||'local')}
function records(){try{const value=JSON.parse(localStorage.getItem(storageKey())||'[]');return Array.isArray(value)?value.filter(r=>r&&['XAU/USD','BTC/USD'].includes(r.symbol)&&Number.isFinite(r.savedAt)&&Number.isFinite(r.price)&&['1min','5min','15min','30min','1h'].includes(r.interval)).slice(0,500):[]}catch{return []}}
